-- الفنادق اللي اسم الجهاز والموقع فيها مكتوبين إنجليزي أصلاً بالعمود العربي
update assets set name_en = name_ar, location_text_en = location_text
where client_id in (select id from clients where name_ar in (
  'فندق مادن - الروضة','فندق مادن - طيبة','فندق نُزُل رويال'
)) and active = true;

